using AcxiomCRM.Data; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using System.Security.Claims;
namespace AcxiomCRM.Controllers;
[Authorize] public class DashboardController:Controller {
 private readonly ApplicationDbContext _db; public DashboardController(ApplicationDbContext db){_db=db;}
 public async Task<IActionResult> Index(){var role=User.IsInRole("Admin")?"Admin":User.IsInRole("Manager")?"Manager":"SalesExecutive"; var uid=User.FindFirstValue(ClaimTypes.NameIdentifier); var customers=_db.Customers.AsQueryable();var leads=_db.Leads.AsQueryable();var opps=_db.Opportunities.AsQueryable();var followups=_db.FollowUps.AsQueryable(); if(role=="SalesExecutive"){customers=customers.Where(x=>x.OwnerId==uid);leads=leads.Where(x=>x.AssignedTo==uid);opps=opps.Where(x=>x.AssignedTo==uid);followups=followups.Where(x=>x.AssignedTo==uid);} ViewBag.Customers=await customers.CountAsync();ViewBag.Leads=await leads.CountAsync();ViewBag.OpenLeads=await leads.CountAsync(x=>x.Status!="Lost"&&x.Status!="Converted"&&x.Status!="Unqualified");ViewBag.Opportunities=await opps.CountAsync();ViewBag.OpenOpportunities=await opps.CountAsync(x=>x.Status=="Open"&&x.Stage!="Won"&&x.Stage!="Lost");ViewBag.Won=await opps.CountAsync(x=>x.Stage=="Won");ViewBag.Lost=await opps.CountAsync(x=>x.Stage=="Lost");ViewBag.Pipeline=await opps.Where(x=>x.Status=="Open"&&x.Stage!="Won"&&x.Stage!="Lost").Select(x=>(decimal?)(x.Amount*x.Probability/100m)).SumAsync()??0;ViewBag.FollowUps=await followups.CountAsync(x=>x.Status=="Planned");ViewBag.LeadChart=await leads.GroupBy(x=>x.Status).Select(g=>new {label=g.Key,count=g.Count()}).ToListAsync();ViewBag.OppChart=await opps.GroupBy(x=>x.Stage).Select(g=>new {label=g.Key,count=g.Count()}).ToListAsync();ViewBag.Monthly=await opps.Where(x=>x.CreatedDate>=DateTime.UtcNow.AddMonths(-5)).GroupBy(x=>new{x.CreatedDate.Year,x.CreatedDate.Month}).Select(g=>new{label=g.Key.Year+"-"+g.Key.Month,count=g.Count()}).OrderBy(x=>x.label).ToListAsync();return View(); }
}
